// ============================================================
// n8n Code node: "Armar Recordatorio"   ->  Mode: Run Once for All Items
// Entrada: filas de Habitos_Log. Config desde "Leer Config".
// ============================================================

const ajustes = $('Settings').first().json;
const CHAT_ID = String(ajustes.cfg_chat_id || '');
const SALUDO = ajustes.cfg_greeting || 'che';

if (!/^-?\d+$/.test(CHAT_ID)) {
  throw new Error('Pone tu chat ID de Telegram en el nodo "Settings"');
}

const TZ = 'America/Argentina/Buenos_Aires';
const hoy = DateTime.now().setZone(TZ).startOf('day');
const lunes = hoy.startOf('week');
const hoyStr = hoy.toFormat('yyyy-MM-dd');
const lunesStr = lunes.toFormat('yyyy-MM-dd');

// Uso Dia/Mes/Anio y no Fecha: son numeros y no dependen de como
// Google Sheets serialice la fecha.
function clave(r) {
  const d = Number(r['Dia']), m = Number(r['Mes']), a = Number(r['Anio']);
  if (!d || !m || !a) return '';
  return a + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}
function si(v) { return String(v == null ? '' : v).trim().toUpperCase() === 'SI'; }
function nombre(r) { return String(r['Habito'] || '').trim(); }

const cfg = $('Leer Config').all()
  .map((i) => i.json)
  .filter((r) => r && r['Habito'] && String(r['Activo'] || '').trim().toUpperCase() !== 'NO');

const log = $input.all().map((i) => i.json).filter((r) => r && r['Habito']);

// "Cumple" ya se calcula sobre el total del dia en "Normalizar Habito":
// alcanza con que una fila del dia diga SI.
const hechoHoy = new Set(
  log.filter((r) => clave(r) === hoyStr && si(r['Cumple'])).map(nombre),
);

const semana = {};
for (const r of log) {
  const k = clave(r);
  if (!k || k < lunesStr || k > hoyStr) continue;
  if (!si(r['Cumple'])) continue;
  const n = nombre(r);
  if (!semana[n]) semana[n] = new Set();
  semana[n].add(k);
}

const diarios = cfg.filter((h) => (Number(h['MetaSemanal']) || 7) >= 6);
const frecuencia = cfg.filter((h) => (Number(h['MetaSemanal']) || 7) < 6);

const faltanHoy = diarios.map(nombre).filter((n) => !hechoHoy.has(n));
const diasQuedan = 8 - hoy.weekday;   // incluye hoy

const lineasSemana = frecuencia.map((h) => {
  const n = nombre(h);
  const meta = Number(h['MetaSemanal']) || 0;
  const hecho = semana[n] ? semana[n].size : 0;
  const restan = Math.max(0, meta - hecho);
  let marca = '';
  if (restan === 0) marca = ' ✅';
  else if (restan > diasQuedan) marca = ' ⚠️';
  return '• ' + n + ' ' + hecho + '/' + meta + marca;
});

const out = [];
out.push('🔔 Cierre del día');
out.push('');
if (faltanHoy.length === 0) {
  out.push('Todo al día, ' + SALUDO + '. Nada pendiente.');
} else {
  out.push('Te faltan hoy:');
  for (const n of faltanHoy) {
    out.push(n.toLowerCase() === 'pasos'
      ? '• ' + n + ' (mirá el reloj, todavía llegás)'
      : '• ' + n);
  }
}
if (lineasSemana.length) {
  out.push('');
  out.push('Semana (desde el lunes, quedan ' + diasQuedan + ' días):');
  for (const l of lineasSemana) out.push(l);
}

return [{ json: { chat_id: CHAT_ID, reply: out.join('\n') } }];

// ============================================================
// n8n Code node: "Buscar Filas a Borrar"   ->  Mode: Run Once for All Items
//
// Entrada: todas las filas de la hoja objetivo (Gastos o Habitos_Log).
// Usa:     "Resolver Puntero" -> hoja + idLote del ultimo guardado.
//
// Devuelve los numeros de fila a borrar, de mayor a menor: borrar de
// abajo hacia arriba evita que los indices se corran.
//
// Busca por ID y no por "ultima fila": si la planilla se toco a mano,
// "la ultima fila" ya no es la que hay que borrar. Usa row_number, que
// el nodo de Sheets trae en cada fila, en vez de calcularlo por indice.
// ============================================================

const saludo = (() => {
  try { return $('User Lookup').first().json.user.greeting || 'che'; }
  catch (e) { return 'che'; }
})();

const { idLote, hoja, resumen } = $('Resolver Puntero').first().json;

const objetivo = [];
const todas = $input.all();
const col = (r, nombre) => {
  const k = Object.keys(r).find((x) => x.trim().toLowerCase() === nombre);
  return k ? String(r[k] == null ? '' : r[k]).trim() : '';
};
todas.forEach((i, idx) => {
  const id = col(i.json, 'id');
  if (id && (id === idLote || id.startsWith(idLote + '-'))) {
    objetivo.push(Number(i.json.row_number) || idx + 2);
  }
});

if (!objetivo.length) {
  return [{
    json: {
      encontrado: false,
      reply: 'Ese registro ya no está, ' + saludo + '. Puede que lo hayas borrado a mano.' +
        ' [debug: busqué ' + idLote + ' en ' + todas.length + ' filas de ' + hoja + ']',
    },
  }];
}

// De mayor a menor, sin repetidos
const filas = [...new Set(objetivo)].sort((a, b) => b - a);

return filas.map((fila) => ({
  json: {
    encontrado: true,
    hoja,
    fila,
    idLote,
    reply: '🗑️ Borrado: ' + (resumen || 'el último registro') +
      '\n\nMandámelo de nuevo como corresponda, ' + saludo + '.',
  },
}));

// ============================================================
// n8n Code node: "Resolver Puntero"   ->  Mode: Run Once for All Items
//
// Entrada: filas de Ultimo_Registro. Devuelve SIEMPRE un solo item,
// asi "Leer Hoja Objetivo" corre una sola vez (antes corria una vez por
// cada fila del historial y el borrado se multiplicaba).
//
// Prioriza la fila con Clave = "ultimo". Si no existe (hoja vieja,
// solo append), usa la ultima fila.
// ============================================================

const saludo = (() => {
  try { return $('User Lookup').first().json.user.greeting || 'che'; }
  catch (e) { return 'che'; }
})();

const filas = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
const puntero = [...filas].reverse().find((r) => String(r['Clave'] || '').trim() === 'ultimo') ||
  filas[filas.length - 1] || {};

const idLote = String(puntero['IDLote'] || '').trim();
const hoja = String(puntero['Hoja'] || '').trim();
const valido = idLote && idLote !== '-' && ['Gastos', 'Habitos_Log'].includes(hoja);

return [{
  json: {
    hayPuntero: !!valido,
    idLote,
    hoja,
    resumen: String(puntero['Resumen'] || '').trim(),
    reply: valido ? '' : 'No tengo nada reciente para borrar, ' + saludo + '.',
  },
}];

// ============================================================
// n8n Code node: "Armar Puntero"   ->  Mode: Run Once for All Items
//
// Corre despues de guardar (habito o gasto) y produce UNA fila para
// Ultimo_Registro. "Guardar Puntero" hace Append or Update sobre la
// columna Clave = "ultimo", asi la hoja tiene siempre una sola fila.
//
// No lee $input: el nodo de Sheets devuelve solo las columnas escritas
// (ID, Habito...), no los campos internos (idLote, esHabito, reply).
// Por eso busca el nodo que armo los datos, en orden de prioridad.
// Tambien arma el texto para "Responder".
// ============================================================

function salida(nodo) {
  try { return $(nodo).all().map((i) => i.json); }
  catch (e) { return []; }   // nodo que no corrio en esta ejecucion
}

const items = ['Normalizar Habito', 'Parse Agente', 'Detectar Intencion']
  .map(salida)
  .find((arr) => arr.length && arr[0].guardar === true) || [];

if (!items.length) throw new Error('Armar Puntero: no encontre que se guardo');

const first = items[0];
const esHabito = first.esHabito === true;

const resumen = esHabito
  ? items.map((r) => r.habito + (r.unidad === 'check' ? '' : ' ' + r.valor + ' ' + r.unidad)).join(', ')
  : items.map((r) => r.categoria + ' ' + (r.moneda === 'USD' ? 'US$' : '$') + r.valor).join(', ');

return [{
  json: {
    Clave: 'ultimo',
    IDLote: String(first.idLote || first.id || ''),
    Hoja: esHabito ? 'Habitos_Log' : 'Gastos',
    Resumen: resumen,
    Timestamp: DateTime.now().setZone('America/Argentina/Buenos_Aires').toISO(),
    chat_id: $('User Lookup').first().json.chat_id,
    reply: first.reply || 'Listo!',
  },
}];

// ============================================================
// n8n Code node: "Normalizar Habito"   ->  Mode: Run Once for All Items
//
// Recibe items de DOS origenes:
//   - "Ruta"      (camino de reglas, origen = "reglas")
//   - "Ruta LLM"  (camino del modelo, origen = "llm")
//
// Valida contra Config_Habitos, calcula "Cumple" sobre el TOTAL DEL DIA
// y arma la respuesta. Vive en un solo lugar para los dos caminos.
//
// Acumulado del dia (columna opcional "Agregacion" en Config_Habitos):
//   - "suma" (default): agua 1L + agua 1L = 2L
//   - "max"  (default para pasos): el Atajo manda el total del dia,
//            asi que se toma el mayor, no la suma
// ============================================================

const TZ = 'America/Argentina/Buenos_Aires';
const hoy = DateTime.now().setZone(TZ).startOf('day');

function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .trim();
}

function n(v) {
  return Number(String(v == null ? '' : v).replace(',', '.')) || 0;
}

// Uso Dia/Mes/Anio y no Fecha: no dependen de como Sheets serialice la fecha.
function clave(r) {
  const d = Number(r['Dia']), m = Number(r['Mes']), a = Number(r['Anio']);
  if (!d || !m || !a) return '';
  return a + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}

// ---------- config y log ----------
const cfg = $('Leer Config Habitos').all()
  .map((i) => i.json)
  .filter((r) => r && r['Habito'] && norm(r['Activo']) !== 'no');

const log = $('Leer Log Habitos').all()
  .map((i) => i.json)
  .filter((r) => r && r['Habito']);

const saludo = (() => {
  try { return $('User Lookup').first().json.user.greeting || 'che'; }
  catch (e) { return 'che'; }
})();

// ---------- formato ----------
function fmt(v, u) {
  const x = Math.round(v * 100) / 100;
  if (u === 'check') return '';
  if (u === 'min') return x + ' min';
  if (u === 'h') return x + ' h';
  if (u === 'L') return x + ' L';
  if (u === 'g') return x + ' g';
  if (u === 'pag') return x + ' pág';
  if (u === 'km') return x + ' km';
  if (u === 'pasos') return x.toLocaleString('es-AR') + ' pasos';
  return x + ' ' + u;
}

// ---------- procesar ----------
const filas = [];
const lineas = [];
let rechazo = null;

for (const item of $input.all()) {
  const j = item.json;

  const h = cfg.find((r) => norm(r['Habito']) === norm(j.habito));
  if (!h) {
    // Solo pasa por el camino del modelo: invento un habito.
    rechazo = 'No tengo ese hábito cargado, ' + saludo +
      '. Los que tengo son: ' + cfg.map((r) => r['Habito']).join(', ') + '.';
    continue;
  }

  const nombre = String(h['Habito']);
  const unidad = j.unidad || String(h['Unidad'] || 'check');
  const minimo = j.minimo != null ? Number(j.minimo) : n(h['Minimo']);
  const valor = unidad === 'check' ? 1 : (Number(j.valor) || minimo);
  const fecha = j.fecha || hoy.toFormat('yyyy-MM-dd');
  const cuando = j.fechaLabel || '';

  const agregacion = norm(h['Agregacion']) || (unidad === 'pasos' ? 'max' : 'suma');

  // Registros previos del mismo habito, mismo dia y misma unidad
  // (Natacion en km y en min no se mezclan)
  const previos = log.filter((r) =>
    clave(r) === fecha &&
    norm(r['Habito']) === norm(nombre) &&
    String(r['Unidad'] || '').trim() === unidad);

  const valoresPrevios = previos.map((r) => n(r['Valor']));
  const yaCumplia = previos.some((r) => String(r['Cumple'] || '').trim().toUpperCase() === 'SI');

  let total;
  if (unidad === 'check') total = 1;
  else if (agregacion === 'max') total = Math.max(valor, ...valoresPrevios);
  else total = valor + valoresPrevios.reduce((a, b) => a + b, 0);

  const cumple = yaCumplia || total >= minimo;
  const detalle = fmt(valor, unidad);
  // Solo muestra el total si difiere de lo que acaba de mandar
  const acumulado = unidad !== 'check' && total !== valor;

  let linea;
  if (unidad === 'check') {
    linea = '✅ ' + nombre + (yaCumplia ? ' (ya estaba anotado)' : '');
  } else if (cumple) {
    linea = '✅ ' + nombre + ' ' + detalle +
      (acumulado ? ' → ' + fmt(total, unidad) + ' en el día' : '') +
      (j.asumido ? ' (asumí el mínimo)' : '');
  } else {
    linea = '🟡 ' + nombre + ' ' + detalle +
      (acumulado ? ' → ' + fmt(total, unidad) + ' en el día' : '') +
      ', te faltan ' + fmt(minimo - total, unidad) + ' para el mínimo';
  }
  lineas.push(linea + cuando);

  filas.push({
    ...j,
    habito: nombre,
    valor,
    unidad,
    minimo,
    cumple: cumple ? 'SI' : 'NO',
    // fecha/dia/mes/anio vienen de "Detectar Intencion" en los dos caminos
    fecha,
    dia: j.dia || hoy.day,
    mes: j.mes || hoy.month,
    anio: j.anio || hoy.year,
  });
}

if (!filas.length) {
  return [{
    json: {
      ok: false,
      guardar: false,
      reply: rechazo || 'No entendí ese hábito, ' + saludo + '.',
    },
  }];
}

const reply = lineas.join('\n') + '\n\nListo, ' + saludo + '!';

return filas.map((f) => ({ json: { ...f, ok: true, guardar: true, reply } }));

// ============================================================
// n8n Code node: "Parse Agente"   ->  Mode: Run Once for All Items
//
// Traduce la salida del modelo local a la forma comun y NO confia en el:
//   - la categoria tiene que existir en la lista de "Detectar Intencion"
//   - el tipo (Ingreso / Gasto Fijo / ...) se deriva de la categoria
//   - el monto tiene que ser > 0 y el mensaje tiene que traer un numero
//     (el 3B inventa montos: "pague la cuota del gym" -> 10000)
//   - las respuestas las arma este nodo, no el modelo: en charla libre
//     el 3B inventa datos ("este mes no anotaste nada")
//
// Sale con "ruta": "habito" | "gasto" | "responder" (lo lee "Ruta LLM").
// La fecha la hereda de "Detectar Intencion".
// ============================================================

const ctx = $('Detectar Intencion').first().json;
const CATEGORIAS = ctx.categorias || {};
const saludo = (ctx.user && ctx.user.greeting) || 'che';

function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .trim();
}

function nuevoId() {
  return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
}

// "50.000" / "50000" / 50000 / "$ 50.000,50" -> numero
function monto(v) {
  if (typeof v === 'number') return v;
  let s = String(v == null ? '' : v).replace(/[^\d.,]/g, '');
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else s = s.replace(/[.,](?=\d{3}(\D|$))/g, '');
  return Number(s) || 0;
}

function limpiarTexto(s) {
  // Emojis rotos que a veces devuelve el modelo local
  return String(s || '')
    .replace(/�/g, '')
    .replace(/([\uD800-\uDBFF])(?![\uDC00-\uDFFF])/g, '')
    .replace(/(^|[^\uD800-\uDBFF])([\uDC00-\uDFFF])/g, '$1')
    .trim();
}

function responder(reply, extra) {
  return { json: { ...ctx, ruta: 'responder', guardar: false, reply, ...(extra || {}) } };
}

const raw = String(($input.first() && $input.first().json.output) || '');

// El modelo a veces envuelve el JSON en markdown o le agrega texto.
let jsonStr = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const start = jsonStr.indexOf('{');
const end = jsonStr.lastIndexOf('}');
if (start !== -1 && end !== -1) jsonStr = jsonStr.slice(start, end + 1);

let p;
try {
  p = JSON.parse(jsonStr);
} catch (e) {
  // Fallar ruidoso: el usuario se entera de que no se guardo nada.
  return [responder('No pude interpretar eso, ' + saludo + '. Probá algo como "supe 50000" o "gym 45 min".', {
    _error: e.message,
    _raw: raw.slice(0, 500),
  })];
}

const tipo = norm(p.tipo);

// ---------- habito ----------
if (tipo === 'habito') {
  const id = nuevoId();
  return [{
    json: {
      ...ctx,
      ruta: 'habito',
      esHabito: true,
      origen: 'llm',
      id: id + '-0',
      idLote: id,
      habito: String(p.habito || ''),
      valor: monto(p.valor),
      unidad: null,   // lo resuelve "Normalizar Habito" desde la config
      minimo: null,
      asumido: monto(p.valor) === 0,
    },
  }];
}

// ---------- plata ----------
if (tipo === 'plata') {
  const valor = monto(p.valor);
  const categoria = Object.keys(CATEGORIAS).find((c) => norm(c) === norm(p.categoria)) || 'Otro';
  const tipoPlata = CATEGORIAS[categoria] || 'Otro Gasto';
  const moneda = norm(p.moneda) === 'usd' ? 'USD' : 'ARS';
  const detalle = limpiarTexto(p.detalle).slice(0, 80);

  if (!(valor > 0) || !/\d/.test(ctx.textoLimpio || '')) {
    return [responder('Entendí que es plata pero no el monto, ' + saludo + '. Mandámelo con el número, ej: "' + (categoria === 'Otro' ? 'gym' : categoria.toLowerCase()) + ' 30000".')];
  }

  const id = nuevoId();
  const plata = (moneda === 'USD' ? 'US$' : '$') + valor.toLocaleString('es-AR');
  const reply = 'Anoté:\n' + (tipoPlata === 'Ingreso' ? '💰 ' : '💸 ') + categoria + ' (' + tipoPlata + ') ' +
    plata + (detalle ? ' · ' + detalle : '') + (ctx.fechaLabel || '') +
    '\n\nListo, ' + saludo + '! Si no era esa categoría, decime "borrá".';

  return [{
    json: {
      ...ctx,
      ruta: 'gasto',
      esHabito: false,
      guardar: true,
      origen: 'llm',
      id,
      idLote: id,
      tipo: tipoPlata,
      categoria,
      detalle,
      moneda,
      valor,
      reply,
    },
  }];
}

// ---------- charla ----------
const t = norm(ctx.textoLimpio);
if (/\b(gracias|genia|genio|grande|buenisimo)\b/.test(t)) {
  return [responder('De nada, ' + saludo + '!')];
}
if (/^(hola|holi|buen dia|buenas|hey|que tal)\b/.test(t)) {
  return [responder('Hola ' + saludo + '! ¿Qué anotamos?')];
}
return [responder('Eso todavía no lo sé hacer, ' + saludo + '. Puedo anotar gastos, ingresos y hábitos. Mandá /ayuda para ver ejemplos.')];

options.systemMessage:
=Clasificás mensajes de {{ $json.user.name }} para anotar su plata y sus hábitos.

Clasificá el mensaje en UNA de estas tres opciones y respondé SOLO con un objeto JSON, sin texto extra.

1) PLATA: un gasto o un ingreso que trae un monto.
{"tipo":"plata","categoria":"<una de CATEGORIAS>","detalle":"<qué fue, 1 a 4 palabras>","moneda":"ARS","valor":<número>}

2) HABITO: algo que hizo para cuidarse (leer, entrenar, tomar agua, dormir...).
{"tipo":"habito","habito":"<uno de HABITOS>","valor":<número, 0 si no dijo>}

3) CHAT: saludo, pregunta o cualquier otra cosa.
{"tipo":"chat"}

CATEGORIAS:
{{ $json.categoriasTexto }}

HABITOS: {{ $json.habitosTexto }}

REGLAS:
- valor es un número sin puntos ni símbolos. "50 lucas" = 50000. "15k" = 15000. "2 palos" = 2000000.
- moneda es "USD" si dice usd, u$s o dólares. Si no, "ARS".
- Si es plata y ninguna categoría encaja, usá "Otro".
- Si no hay ningún número de plata, NO es plata.
- Comida, café, bar o restaurante = "Comidas afuera". Taxi, cabify, remis = "Uber". Ropa, regalos, farmacia = "Otro".

EJEMPLOS:
"me gaste 3000 en un cafe" -> {"tipo":"plata","categoria":"Comidas afuera","detalle":"café","moneda":"ARS","valor":3000}
"cobre 2000 dolares de un cliente" -> {"tipo":"plata","categoria":"Freelance","detalle":"","moneda":"USD","valor":2000}
"compre una remera 25 lucas" -> {"tipo":"plata","categoria":"Otro","detalle":"remera","moneda":"ARS","valor":25000}
"hice una hora de pileta" -> {"tipo":"habito","habito":"Natacion","valor":60}
"hola" -> {"tipo":"chat"}
"cuanto gaste este mes?" -> {"tipo":"chat"}

