// ============================================================
// n8n Code node: "Detectar Intencion"   ->  Mode: Run Once for All Items
//
// Entrada:  se ignora (son las filas de "Leer Log Habitos", que las usa
//           "Normalizar Habito"). La config sale de "Leer Config Habitos".
// Salida:   1+ items, todos con el mismo campo "ruta":
//             - "deshacer"  : borrar el ultimo registro
//             - "habito"    : uno o mas habitos reconocidos por reglas
//             - "gasto"     : uno o mas gastos/ingresos reconocidos por reglas
//             - "responder" : contestar sin guardar (ayuda, negacion, etc.)
//             - "llm"       : no se reconocio nada, va al modelo
//
// Las reglas resuelven lo comun ("supe 50000", "gym 45 min", "agua 2l").
// El modelo local (3B) solo ve lo que las reglas no entendieron.
// La FECHA se resuelve siempre aca, incluso para la ruta "llm".
// ============================================================

const TZ = 'America/Argentina/Buenos_Aires';
const hoy = DateTime.now().setZone(TZ).startOf('day');

const base = $('User Lookup').first().json;
const saludo = (base.user && base.user.greeting) || 'che';
const textoOriginal = String(base.text || '');

// ============================================================
// CATEGORIAS DE PLATA
// Unica fuente de verdad: "Parse Agente" y el prompt del modelo
// leen esta misma lista desde la salida de este nodo.
// ============================================================
const CATEGORIAS = {
  'Salario': 'Ingreso', 'Freelance': 'Ingreso',
  'Agua': 'Gasto Fijo', 'Luz': 'Gasto Fijo', 'Gym': 'Gasto Fijo', 'Telefono': 'Gasto Fijo',
  'Impuestos': 'Gasto Fijo', 'Suscripciones': 'Gasto Fijo', 'Expensas': 'Gasto Fijo',
  'Alquiler': 'Gasto Fijo', 'Wifi': 'Gasto Fijo',
  'Supermercado': 'Gasto Variable', 'Gasolina': 'Gasto Variable', 'Uber': 'Gasto Variable',
  'Futbol': 'Gasto Variable', 'Casa': 'Gasto Variable',
  'Otro': 'Otro Gasto', 'Comidas afuera': 'Otro Gasto', 'Cine': 'Otro Gasto', 'Mercado libre': 'Otro Gasto',
};

// Alias -> categoria. El nombre de cada categoria ya cuenta como alias.
// "Otro" no tiene alias a proposito: si no se sabe, que decida el modelo.
const ALIAS_PLATA = {
  'sueldo': 'Salario', 'honorarios': 'Freelance', 'cliente': 'Freelance',
  'gimnasio': 'Gym', 'cuota gym': 'Gym',
  'tel': 'Telefono', 'celular': 'Telefono',
  'mono': 'Impuestos', 'monotributo': 'Impuestos', 'afip': 'Impuestos', 'arca': 'Impuestos',
  'netflix': 'Suscripciones', 'spotify': 'Suscripciones', 'youtube': 'Suscripciones', 'disney': 'Suscripciones',
  'expensa': 'Expensas',
  'renta': 'Alquiler', 'alquileres': 'Alquiler',
  'internet': 'Wifi',
  'supe': 'Supermercado', 'super': 'Supermercado', 'coto': 'Supermercado',
  'jumbo': 'Supermercado', 'carrefour': 'Supermercado', 'chino': 'Supermercado',
  'nafta': 'Gasolina', 'ypf': 'Gasolina', 'shell': 'Gasolina', 'axion': 'Gasolina',
  'taxi': 'Uber', 'cabify': 'Uber', 'didi': 'Uber', 'remis': 'Uber',
  'fulbo': 'Futbol', 'cancha': 'Futbol',
  'resto': 'Comidas afuera', 'comida': 'Comidas afuera', 'almuerzo': 'Comidas afuera',
  'cena': 'Comidas afuera', 'delivery': 'Comidas afuera', 'rappi': 'Comidas afuera',
  'pedidosya': 'Comidas afuera', 'pizza': 'Comidas afuera', 'pizzas': 'Comidas afuera',
  'cafe': 'Comidas afuera', 'sushi': 'Comidas afuera', 'hamburguesa': 'Comidas afuera',
  'empanadas': 'Comidas afuera',
  'meli': 'Mercado libre', 'ml': 'Mercado libre', 'mercadolibre': 'Mercado libre',
};

// Tope por defecto cuando Config_Habitos no trae "Max". Evita que
// "agua 14200" (la factura) se anote como 14200 litros tomados.
const MAX_DEFAULT = { L: 20, min: 600, h: 24, pasos: 150000, km: 300, pag: 2000, g: 1000 };

// ---------- helpers ----------
function norm(s) {
  return String(s == null ? '' : s)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[‘’`]/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function num(s) {
  return parseFloat(String(s).replace(',', '.'));
}

function esc(s) {
  return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function nuevoId() {
  return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
}

function palabra(alias) {
  // "\b" no sirve para alias que terminan en simbolo ("disney+")
  return new RegExp('(?:^|[^a-z0-9])' + esc(alias) + '(?![a-z0-9])');
}

function responder(reply) {
  return [{ json: { ...base, ruta: 'responder', guardar: false, reply } }];
}

const t0 = norm(textoOriginal);

// ============================================================
// 0. mensajes sin texto y ayuda
// ============================================================
if (!t0) {
  return responder('Por ahora solo entiendo texto, ' + saludo + '.');
}

if (/^\/?(start|help|ayuda)\b/.test(t0)) {
  return responder([
    'Hola ' + saludo + '! Mandame cosas como:',
    '• supe 50000',
    '• nafta 30 lucas ayer',
    '• salario 1500 usd',
    '• gym 45 min y agua 2l',
    '• leí 20 pág el martes',
    '• borrá lo último',
  ].join('\n'));
}

// ============================================================
// 1. DESHACER
// Se evalua primero: si el usuario esta corrigiendo, el texto no
// tiene que interpretarse como un registro nuevo.
// ============================================================

// "no fui al gym" es una negacion de habito, no un deshacer.
const ES_NEGACION_HABITO =
  /\bno\s+(?:fui|hice|lei|nade|medite|entrene|tome|dormi|camine|corri)\b/.test(t0);

// Correcciones al inicio del mensaje: valen aunque haya numeros
// ("no, era 5000" -> borra y pide que lo mande de nuevo).
const DESHACER_INICIO = /^(no|nop|uy|ups|ay)[,.\s]+(era|fue|es|estaba)\b/;

// Pedidos explicitos: solo si el mensaje NO trae numeros, para que
// "cena 20000, estaba mal la comida" no borre nada.
const PATRONES_DESHACER = [
  /\b(borra|borralo|borrala|borrar|borre|elimina|eliminalo|eliminar)\b/,
  /\b(deshace|deshacelo|deshacer|cancela|cancelalo|cancelar)\b/,
  /\b(me equivoque|equivocado|equivocada)\b/,
  /\b(esta mal|estaba mal|es un error|fue un error)\b/,
  /^(ese|eso|esa|ese registro)\s+(no|esta mal|estaba mal)\b/,
];

const quiereDeshacer = !ES_NEGACION_HABITO && (
  DESHACER_INICIO.test(t0) ||
  (!/\d/.test(t0) && PATRONES_DESHACER.some((re) => re.test(t0)))
);

if (quiereDeshacer) {
  return [{ json: { ...base, ruta: 'deshacer', texto: textoOriginal } }];
}

// ============================================================
// 2. config de habitos
// ============================================================
const cfg = $('Leer Config Habitos').all()
  .map((i) => i.json)
  .filter((r) => r && r['Habito'] && norm(r['Activo']) !== 'no')
  .map((r) => {
    const unidad = String(r['Unidad'] || 'check').trim();
    const maxCfg = Number(String(r['Max'] == null ? '' : r['Max']).replace(',', '.'));
    return {
      habito: String(r['Habito']).trim(),
      alias: [norm(r['Habito'])]
        .concat(String(r['Alias'] || '').split(',').map(norm))
        .filter(Boolean),
      unidad,
      minimo: Number(String(r['Minimo']).replace(',', '.')) || 0,
      unidadAlt: String(r['UnidadAlt'] || '').trim(),
      minimoAlt: Number(String(r['MinimoAlt']).replace(',', '.')) || 0,
      max: maxCfg > 0 ? maxCfg : (MAX_DEFAULT[unidad] || Infinity),
    };
  });

// alias mas largo primero: "deep work" gana sobre "dw"
cfg.forEach((h) => h.alias.sort((a, b) => b.length - a.length));

// ============================================================
// 3. resolver fecha (se ejecuta SIEMPRE)
// ============================================================
const DIAS = { domingo: 7, lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6 };

function resolverFecha(t) {
  let f = hoy;
  let limpio = t;

  if (/\banteayer\b/.test(t)) {
    f = hoy.minus({ days: 2 });
    limpio = t.replace(/\banteayer\b/g, ' ');
  } else if (/\bayer\b/.test(t)) {
    f = hoy.minus({ days: 1 });
    limpio = t.replace(/\bayer\b/g, ' ');
  } else if (/\bhoy\b/.test(t)) {
    limpio = t.replace(/\bhoy\b/g, ' ');
  } else {
    const md = t.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/);
    const wd = Object.keys(DIAS).find((d) => new RegExp('\\b' + d + '\\b').test(t));
    if (md && Number(md[2]) >= 1 && Number(md[2]) <= 12) {
      let anio = hoy.year;
      if (md[3]) anio = md[3].length === 2 ? 2000 + Number(md[3]) : Number(md[3]);
      f = DateTime.fromObject({ year: anio, month: Number(md[2]), day: Number(md[1]) }, { zone: TZ });
      if (!md[3] && f > hoy) f = f.minus({ years: 1 });
      limpio = t.replace(md[0], ' ');
    } else if (wd) {
      const target = DIAS[wd];
      for (let i = 1; i <= 7; i++) {
        const c = hoy.minus({ days: i });
        if (c.weekday === target) { f = c; break; }
      }
      limpio = t.replace(new RegExp('\\b(?:el |los )?' + wd + '\\b'), ' ');
    }
  }
  if (!f || !f.isValid || f > hoy) f = hoy;
  return { fecha: f, texto: limpio.replace(/\s+/g, ' ').trim() };
}

const { fecha, texto } = resolverFecha(t0);
const esHoy = fecha.hasSame(hoy, 'day');

// Se adjunta a TODAS las salidas, incluida la que va al modelo.
const fechaCtx = {
  fecha: fecha.toFormat('yyyy-MM-dd'),
  dia: fecha.day,
  mes: fecha.month,
  anio: fecha.year,
  esHoy,
  fechaLabel: esHoy ? '' : ' (' + fecha.toFormat('dd/MM') + ')',
};

// ============================================================
// 4. fragmentos
// "12,5" -> "12.5" antes de cortar por comas.
// "+" solo separa si esta suelto ("gym + agua"), no en "disney+".
// ============================================================
const protegido = texto.replace(/(\d),(\d)/g, '$1.$2');
const fragmentos = protegido
  .split(/\s*(?:,|;|\s\+|\by\b|\btambien\b)\s*/)
  .map((f) => f.trim())
  .filter(Boolean);

// ============================================================
// 5. HABITOS
// ============================================================
const NUM_PALABRAS = {
  'medio': '0.5', 'media': '0.5', 'un': '1', 'una': '1', 'uno': '1', 'dos': '2',
  'tres': '3', 'cuatro': '4', 'cinco': '5', 'seis': '6', 'siete': '7', 'ocho': '8',
  'nueve': '9', 'diez': '10',
};

function numerosEnPalabras(t) {
  return t.replace(/\b(medio|media|un|una|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\b/g,
    (m) => NUM_PALABRAS[m]);
}

const UNI_RE = {
  min: "(?:min|mins|minuto|minutos|m|')",
  h: '(?:hs|hrs|hr|horas|hora|h)',
  L: '(?:litros|litro|lts|lt|l)',
  g: '(?:gramos|gramo|grs|gr|g)',
  pag: '(?:paginas|pagina|pags|pag|pg)',
  km: '(?:kilometros|kilometro|kms|km)',
  pasos: '(?:pasos|paso|steps)',
};

function buscar(t, unidad) {
  const pat = UNI_RE[unidad];
  if (!pat) return null;
  const m = t.match(new RegExp('(\\d+(?:\\.\\d+)?)\\s*' + pat + '(?![a-z])'));
  return m ? num(m[1]) : null;
}

function extraerValor(frag, h) {
  if (h.unidad === 'check') return { valor: 1, unidad: 'check', asumido: false, alt: false };

  // "me dormi a las 2" es una hora del reloj, no una duracion
  let f = numerosEnPalabras(frag).replace(/\ba (?:la|las)\s+\d{1,2}(?:[:.]\d{2})?\b/g, ' ');
  // "8.500 pasos" -> "8500 pasos" (punto de miles)
  if (h.unidad === 'pasos') f = f.replace(/\b(\d{1,3}(?:\.\d{3})+)\b/g, (m) => m.replace(/\./g, ''));

  if (h.unidadAlt) {
    const v = buscar(f, h.unidadAlt);
    if (v !== null) return { valor: v, unidad: h.unidadAlt, asumido: false, alt: true };
  }

  // horas + minutos combinados: "1h30", "1 hora 30", "1.5h"
  if (h.unidad === 'min' || h.unidad === 'h') {
    const hm = f.match(/(\d+(?:\.\d+)?)\s*(?:hs|hrs|hr|horas|hora|h)(?![a-z])\s*(?:(\d{1,2})\s*(?:min|mins|minutos|m|')?)?/);
    if (hm) {
      const total = num(hm[1]) * 60 + (hm[2] ? parseInt(hm[2], 10) : 0);
      if (h.unidad === 'min') return { valor: Math.round(total), unidad: 'min', asumido: false, alt: false };
      return { valor: Math.round((total / 60) * 100) / 100, unidad: 'h', asumido: false, alt: false };
    }
  }

  const v = buscar(f, h.unidad);
  if (v !== null) return { valor: v, unidad: h.unidad, asumido: false, alt: false };

  if (h.unidad === 'pasos') {
    const k = f.match(/(\d+(?:\.\d+)?)\s*(?:k|mil)(?![a-z])/);
    if (k) return { valor: num(k[1]) * 1000, unidad: 'pasos', asumido: false, alt: false };
  }

  const n = f.match(/(\d+(?:\.\d+)?)/);
  if (n) return { valor: num(n[1]), unidad: h.unidad, asumido: false, alt: false };

  return { valor: h.minimo, unidad: h.unidad, asumido: true, alt: false };
}

// "pague la cuota del gym" es plata aunque mencione un habito
const VERBOS_PLATA = /\b(pague|pago|pagar|cuota|factura|abone|gaste|compre|cobre|cobro)\b/;

function matchHabito(frag, usados) {
  if (VERBOS_PLATA.test(frag)) return null;
  for (const h of cfg) {
    if (usados.has(h.habito)) continue;
    // hasta 3 letras de sufijo para plurales y variantes cortas ("gyms", "aguas")
    const hit = h.alias.find((a) => new RegExp('\\b' + esc(a) + '\\w{0,3}\\b').test(frag));
    if (!hit) continue;
    const v = extraerValor(frag, h);
    if (v.valor === null || isNaN(v.valor)) continue;
    // anti-colision con gastos: "gym 30000" = cuota, "agua 12000" = factura
    if (!v.alt && v.valor > h.max) continue;
    return {
      habito: h.habito,
      valor: v.valor,
      unidad: v.unidad,
      minimo: v.alt ? h.minimoAlt : h.minimo,
      asumido: v.asumido,
    };
  }
  return null;
}

// ============================================================
// 6. GASTOS por reglas
// ============================================================
const aliasPlata = Object.keys(CATEGORIAS).map((c) => [norm(c), c])
  .concat(Object.entries(ALIAS_PLATA).map(([a, c]) => [norm(a), c]))
  .filter(([, c]) => c !== 'Otro')
  .sort((a, b) => b[0].length - a[0].length);

const MULT = { k: 1e3, mil: 1e3, luca: 1e3, lucas: 1e3, palo: 1e6, palos: 1e6, millon: 1e6, millones: 1e6, m: 1e6 };

// "50000", "50.000", "12.500.50", "15k", "50 lucas", "2 palos", "1.5 millones"
function parseMontos(t) {
  const re = /(\d+(?:\.\d+)*)\s*(k|mil|lucas|luca|palos|palo|millones|millon|m)?(?![a-z0-9])/g;
  const out = [];
  let m;
  while ((m = re.exec(t)) !== null) {
    const raw = m[1];
    const grupos = raw.split('.');
    let n;
    if (grupos.length > 1 && grupos.slice(1).every((g) => g.length === 3)) {
      n = Number(grupos.join(''));                       // 50.000 -> 50000
    } else if (grupos.length > 2) {
      n = Number(grupos.slice(0, -1).join('') + '.' + grupos[grupos.length - 1]); // 12.500.50
    } else {
      n = Number(raw);
    }
    if (m[2]) n *= MULT[m[2]];
    if (!isNaN(n)) out.push({ valor: Math.round(n * 100) / 100, token: m[0] });
  }
  return out;
}

const RELLENO = /\b(me|te|le|en|el|la|los|las|de|del|al|un|una|por|para|con|que|pague|gaste|compre|cobre|pagaron|gasto|pago|cobro|ars|pesos|peso|usd|dolares|dolar|verdes?)\b/g;

function matchGasto(frag) {
  const hit = aliasPlata.find(([a]) => palabra(a).test(frag));
  const montos = parseMontos(frag);
  if (!hit && !montos.length) return { tipo: 'vacio' };
  if (!hit || !montos.length) return { tipo: 'ambiguo' };

  // El monto es el numero mas grande: "2 pizzas 16000" -> 16000
  const monto = montos.reduce((a, b) => (b.valor > a.valor ? b : a));
  if (monto.valor <= 0) return { tipo: 'ambiguo' };

  const moneda = /(\busd\b|u\$s|us\$|\bdolar|\bdolares\b|\bverdes?\b)/.test(frag) ? 'USD' : 'ARS';
  const detalle = frag
    .replace(palabra(hit[0]), ' ')
    .replace(monto.token, ' ')
    .replace(/u\$s|us\$|\$/g, ' ')
    .replace(RELLENO, ' ')
    .replace(/[^a-z0-9ñ ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return {
    tipo: 'gasto',
    categoria: hit[1],
    tipoPlata: CATEGORIAS[hit[1]],
    valor: monto.valor,
    moneda,
    detalle: detalle.length > 2 ? detalle : '',
  };
}

// ============================================================
// 7. clasificar cada fragmento
// ============================================================
const habitos = [];
const gastos = [];
let ambiguo = false;
const usados = new Set();

for (const frag of fragmentos) {
  const h = matchHabito(frag, usados);
  if (h) {
    habitos.push(h);
    usados.add(h.habito);
    continue;
  }
  const g = matchGasto(frag);
  if (g.tipo === 'gasto') {
    gastos.push(g);
  } else if (gastos.length && !parseMontos(frag).length) {
    // fragmento sin monto despues de un gasto: es detalle del anterior
    // ("cena 20000, con los chicos")
    const ult = gastos[gastos.length - 1];
    ult.detalle = (ult.detalle + ' ' + frag).trim();
  } else if (g.tipo === 'ambiguo') {
    ambiguo = true;
  }
}

const negado = /^(?:no |hoy no |ayer no )/.test(t0) || ES_NEGACION_HABITO;

// Contexto que necesitan el modelo y "Parse Agente"
const llmCtx = {
  categorias: CATEGORIAS,
  categoriasTexto: Object.entries(
    Object.entries(CATEGORIAS).reduce((acc, [c, t]) => {
      (acc[t] = acc[t] || []).push(c);
      return acc;
    }, {}),
  ).map(([t, cs]) => '- ' + t + ': ' + cs.join(', ')).join('\n'),
  habitosTexto: cfg.map((h) => h.habito).join(', '),
};

// ============================================================
// 8. salida
// ============================================================
if (negado && habitos.length) {
  return responder('Ok, no anoto ' + habitos.map((h) => h.habito).join(', ') + '. Mañana se recupera, ' + saludo + '!');
}

if (habitos.length && gastos.length) {
  return responder('Mandame los hábitos y la plata en mensajes separados, ' + saludo + '. Así si hay que borrar, borro lo correcto.');
}

const idLote = nuevoId();

if (habitos.length && !negado) {
  return habitos.map((e, i) => ({
    json: {
      ...base,
      ...fechaCtx,
      ruta: 'habito',
      esHabito: true,
      origen: 'reglas',
      id: idLote + '-' + i,
      idLote,
      habito: e.habito,
      valor: e.valor,
      unidad: e.unidad,
      minimo: e.minimo,
      asumido: e.asumido,
      texto: textoOriginal,
    },
  }));
}

if (gastos.length && !ambiguo && !negado) {
  const fmtPlata = (v, mon) => (mon === 'USD' ? 'US$' : '$') + Number(v).toLocaleString('es-AR');
  const lineas = gastos.map((g) =>
    (g.tipoPlata === 'Ingreso' ? '💰 ' : '💸 ') + g.categoria + ' (' + g.tipoPlata + ') ' +
    fmtPlata(g.valor, g.moneda) + (g.detalle ? ' · ' + g.detalle : '') + fechaCtx.fechaLabel);
  const reply = 'Anoté:\n' + lineas.join('\n') + '\n\nListo, ' + saludo + '!';

  return gastos.map((g, i) => ({
    json: {
      ...base,
      ...fechaCtx,
      ruta: 'gasto',
      esHabito: false,
      guardar: true,
      origen: 'reglas',
      id: gastos.length === 1 ? idLote : idLote + '-' + i,
      idLote,
      tipo: g.tipoPlata,
      categoria: g.categoria,
      detalle: g.detalle,
      moneda: g.moneda,
      valor: g.valor,
      texto: textoOriginal,
      reply,
    },
  }));
}

// Al modelo. Recibe la fecha ya resuelta y el texto sin palabras de fecha.
return [{
  json: {
    ...base,
    ...fechaCtx,
    ...llmCtx,
    ruta: 'llm',
    esHabito: false,
    textoLimpio: texto || t0,
    texto: textoOriginal,
  },
}];

// ============================================================
// n8n Code node: "User Lookup"   ->  Mode: Run Once for All Items
//
// Lee tu chat_id, nombre y saludo del nodo "Settings" (un solo lugar para configurar).
// n8n 2.x bloquea $env en los nodos Code, por eso la config vive en un nodo.
// ============================================================

const cfg = $('Settings').first().json;
const CHAT_ID = String(cfg.cfg_chat_id || '');
const USUARIO = { name: cfg.cfg_name, greeting: cfg.cfg_greeting };

if (!/^-?\d+$/.test(CHAT_ID)) {
  throw new Error('Pone tu chat ID de Telegram en el nodo "Settings"');
}

const j = $input.first().json;
const canal = j.canal || 'telegram';
const from = String(j.from == null ? '' : j.from).trim();

// iPhone ya viene autenticado por el Header Auth del Webhook.
// Telegram: igualdad exacta, nunca includes() (un id que contenga
// el tuyo como substring pasaria el filtro).
const conocido = canal === 'iphone' || from === CHAT_ID;

return [{
  json: {
    canal,
    from,
    text: String(j.text || ''),
    chat_id: canal === 'iphone' ? CHAT_ID : String(j.chat_id || ''),
    user: conocido ? USUARIO : null,
    isKnownUser: conocido,
  },
}];

// El Atajo de iOS manda { "text": "8500 pasos" } con el header X-Webhook-Token.
// El token ya lo valida el Webhook (Header Auth), asi que aca solo
// normalizamos a la misma forma que sale de "Extraer Datos".
// El chat_id lo completa "User Lookup".
const j = $input.first().json;
const body = j.body || j;
return [{
  json: {
    canal: 'iphone',
    from: '',
    chat_id: '',
    text: String(body.text || ''),
  },
}];
